            ctx.lineTo(-size * 0.05, -size * 0.38);
            ctx.lineTo(0, -size * 0.58);
            ctx.lineTo(size * 0.05, -size * 0.38);
            ctx.lineTo(size * 0.20, -size * 0.50);
            ctx.lineTo(size * 0.12, -size * 0.30);
